# gradient = autodiff (dev/plan.md 3.10 stage 1, C236): gradients generated by
# central differences of the log density, for C++ and for other languages

autodiff_model = function(prior_gradient, likelihood_gradient, move = "metropolis_hastings(langevin(theta, [[0.1, 0], [0, 0.1]], 1))",
                          extra = character(0))
{
  c("ilike 1.0", "data { y = [1.2, 0.4, 2.1] }", "model {",
    paste("  prior p = density(log = cpp::log_prior, simulate = cpp::sim_prior, gradient = ", prior_gradient, ")", sep = ""),
    paste("  factor lik = density(log = cpp::log_lik, gradient = ", likelihood_gradient, ")", sep = ""), "}",
    "cpp {",
    "double log_prior(const Parameters &parameters) { return dnorm(parameters[\"theta\"][0], 0, 2) + dnorm(parameters[\"theta\"][1], 0, 2); }",
    "Parameters sim_prior(RandomNumberGenerator &rng) { arma::colvec t(2); t(0) = rnorm(rng, 0, 2); t(1) = rnorm(rng, 0, 2); return Parameters(\"theta\", t); }",
    "double log_lik(const Parameters &parameters, const Data &data)",
    "{ double out = 0; arma::colvec y = data[\"y\"];",
    "  for (size_t i = 0; i < y.n_elem; ++i) out += dnorm(y(i), parameters[\"theta\"][0], exp(parameters[\"theta\"][1])); return out; }",
    "arma::mat prior_gradient(const std::string &variable, const Parameters &parameters) { return -parameters[\"theta\"] / 4.0; }",
    "arma::mat lik_gradient(const std::string &variable, const Parameters &parameters, const Data &data)",
    "{ arma::colvec y = data[\"y\"]; double m = parameters[\"theta\"][0], s = exp(parameters[\"theta\"][1]); arma::mat g(2, 1);",
    "  g(0) = arma::sum(y - m) / (s * s); g(1) = arma::sum(-1.0 + arma::square(y - m) / (s * s)); return g; }",
    "}", "algorithm mcmc {", paste("  move m =", move), "  termination = iterations(200)", "}", extra)
}

autodiff_exact = function(t)
{
  y = c(1.2, 0.4, 2.1); s = exp(t[2])
  c(-t[1] / 4 + sum(y - t[1]) / s^2, -t[2] / 4 + sum(-1 + (y - t[1])^2 / s^2))
}

test_that("gradient = autodiff gives the gradient of a log density written in C++", {
  f = tempfile(fileext = ".ilike")
  on.exit(unlink(c(f, "autodiff_a", "autodiff_b"), recursive = TRUE), add = TRUE)
  writeLines(autodiff_model("autodiff", "autodiff(finite_difference)"), f)
  expect_message(m <- ilike::compile(f), "finite differences")
  theta = c(0.7, -0.3)
  checked = ilike::check_gradient(m, list(theta = theta))
  expect_equal(checked$gradient, autodiff_exact(theta), tolerance = 1e-7)
  expect_true(all(checked$error < 1e-6))
  # with metropolis_hastings, the chain is that of the exact gradient (the
  # gradients differ by ~1e-10, which changes no decision here)
  ilike::MCMC(m, results_name = "autodiff_a", seed = 1, initial_values = list(list(theta = theta)))
  writeLines(autodiff_model("cpp::prior_gradient", "cpp::lik_gradient"), f)
  ilike::MCMC(ilike::compile(f), results_name = "autodiff_b", seed = 1, initial_values = list(list(theta = theta)))
  expect_equal(ilike::load_mcmc_output("autodiff_a")$Value, ilike::load_mcmc_output("autodiff_b")$Value, tolerance = 1e-6)
})

test_that("gradient = autodiff gives the gradient of a log density written in R", {
  f = tempfile(fileext = ".ilike")
  on.exit(unlink(f), add = TRUE)
  writeLines(c("ilike 1.0", "data { y = r::c(1.2, 0.4, 2.1) }", "model {",
               "  prior p = density(log = r::sum(dnorm(theta, 0, 2, log = TRUE)), simulate = r::list(theta = rnorm(2, 0, 2)), gradient = autodiff)",
               "  factor lik = density(log = r::sum(dnorm(y, theta[1], exp(theta[2]), log = TRUE)), gradient = autodiff)", "}",
               "algorithm mcmc {", "  move m = metropolis_hastings(langevin(theta, [[0.1, 0], [0, 0.1]], 1))", "  termination = iterations(10)", "}"), f)
  m = suppressMessages(ilike::compile(f))
  theta = c(0.7, -0.3)
  expect_equal(as.vector(ilike:::evaluate_gradient_log(m, list(theta = theta), "theta")), autodiff_exact(theta), tolerance = 1e-7)
  expect_equal(as.vector(ilike:::evaluate_gradient_log(m, list(theta = theta), "theta", index = 2)),
               autodiff_exact(theta) + theta / 4, tolerance = 1e-7)
})

test_that("gradient = autodiff is refused where it cannot be used", {
  f = tempfile(fileext = ".ilike")
  on.exit(unlink(f), add = TRUE)
  refused = function(lines, message)
  {
    writeLines(lines, f)
    expect_error(suppressMessages(ilike::compile(f)), message, fixed = TRUE)
  }
  refused(autodiff_model("autodiff", "cpp::lik_gradient", move = "unadjusted(langevin(theta, [[0.1, 0], [0, 0.1]], 1))"),
          "unadjusted moves need exact gradients")
  refused(autodiff_model("autodiff(backward)", "cpp::lik_gradient"), "autodiff takes no argument")
  lines = autodiff_model("autodiff", "cpp::lik_gradient")
  lines[4] = "  prior p = density(simulate = cpp::sim_prior, gradient = autodiff)"
  refused(lines, "the log density is needed too")
})

# (C237) stage 2: forward mode for log densities written as templates
autodiff_template_model = function(gradient, move = "unadjusted(langevin(theta, [[0.01, 0], [0, 0.01]], 1))")
{
  c("ilike 1.0", "data { y = [1.2, 0.4, 2.1] }", "model {",
    paste("  prior p = density(log = cpp::log_prior, simulate = cpp::sim_prior, gradient = ", gradient, ")", sep = ""),
    paste("  factor lik = density(log = cpp::log_lik, gradient = ", gradient, ")", sep = ""), "}",
    "cpp {",
    "template <class T> T log_prior(const ParametersT<T> &parameters) { return dnorm(parameters[\"theta\"][0], 0, 2) + dnorm(parameters[\"theta\"](1), 0, 2); }",
    "Parameters sim_prior(RandomNumberGenerator &rng) { arma::colvec t(2); t(0) = rnorm(rng, 0, 2); t(1) = rnorm(rng, 0, 2); return Parameters(\"theta\", t); }",
    "template <class T> T log_lik(const ParametersT<T> &parameters, const Data &data)",
    "{ arma::colvec y = data[\"y\"]; T m = parameters[\"theta\"][0]; T s = exp(parameters[\"theta\"][1]); T out = 0;",
    "  for (size_t i = 0; i < y.n_elem; ++i) out += dnorm(y(i), m, s); return out; }",
    "}", "algorithm mcmc {", paste("  move m =", move), "  termination = iterations(200)", "}")
}

test_that("gradient = autodiff differentiates a log density written as a template exactly (reverse and forward mode)", {
  f = tempfile(fileext = ".ilike")
  on.exit(unlink(c(f, "autodiff_c", "autodiff_d"), recursive = TRUE), add = TRUE)
  writeLines(autodiff_template_model("autodiff"), f)
  expect_silent(m <- ilike::compile(f)) # (exact: no note)
  theta = c(0.7, -0.3)
  expect_equal(as.vector(ilike:::evaluate_gradient_log(m, list(theta = theta), "theta")), autodiff_exact(theta), tolerance = 1e-13)
  # (the default is forward mode for fewer than 10 elements; reverse mode asked for)
  writeLines(autodiff_template_model("autodiff(reverse)"), f)
  m_reverse = ilike::compile(f)
  expect_equal(as.vector(ilike:::evaluate_gradient_log(m_reverse, list(theta = theta), "theta")), autodiff_exact(theta), tolerance = 1e-13)
  # the double instance is the log density
  expect_equal(ilike::evaluate_log(m, parameters = list(theta = theta)),
               sum(dnorm(theta, 0, 2, log = TRUE)) + sum(dnorm(c(1.2, 0.4, 2.1), theta[1], exp(theta[2]), log = TRUE)), tolerance = 1e-13)
  # an exact gradient: unadjusted moves accept it, and give the chain of the hand-written gradient
  ilike::MCMC(m, results_name = "autodiff_c", seed = 1, initial_values = list(list(theta = theta)))
  writeLines(sub("move m = metropolis_hastings\\(langevin\\(theta, \\[\\[0.1, 0\\], \\[0, 0.1\\]\\], 1\\)\\)",
                 "move m = unadjusted(langevin(theta, [[0.01, 0], [0, 0.01]], 1))", autodiff_model("cpp::prior_gradient", "cpp::lik_gradient")), f)
  ilike::MCMC(ilike::compile(f), results_name = "autodiff_d", seed = 1, initial_values = list(list(theta = theta)))
  expect_equal(ilike::load_mcmc_output("autodiff_c")$Value, ilike::load_mcmc_output("autodiff_d")$Value, tolerance = 1e-10)
  # autodiff(finite_difference) still differences it (through the double instance)
  writeLines(autodiff_template_model("autodiff(finite_difference)", move = "metropolis_hastings(langevin(theta, [[0.1, 0], [0, 0.1]], 1))"), f)
  m = suppressMessages(ilike::compile(f))
  expect_equal(as.vector(ilike:::evaluate_gradient_log(m, list(theta = theta), "theta")), autodiff_exact(theta), tolerance = 1e-7)
})

test_that("the functions and densities of the autodiff numbers have the right derivatives", {
  f = tempfile(fileext = ".ilike")
  on.exit(unlink(f), add = TRUE)
  writeLines(c("ilike 1.0", "model {", "  factor lik = density(log = cpp::log_lik, gradient = autodiff)", "}", "cpp {",
               "template <class T> T log_lik(const ParametersT<T> &parameters)", "{",
               "  T a = parameters[\"a\"][0], b = parameters[\"b\"][0], c = parameters[\"b\"][1];",
               "  T out = pow(a, 2.5) + pow(2.0, b) + pow(a, b) + sqrt(a) * log1p(b) + expm1(c) - sin(a) * cos(b) + tan(c / 4)",
               "        + tanh(a - b) + atan(c) + abs(b - a) + lgamma(a + b) + 1.0 / (a + c) - a / 3.0 + sinh(c) * cosh(b / 2);",
               "  out += dnorm(1.1, a, b) + dlnorm(a, c, b) + dexp(a, b) + dgamma(a, b, c) + dpois(3, a) + dunif(c, -a, b) + dnorm(c - 1);",
               "  out *= 1.5; out -= a; out /= b;",
               "  return (a < b) ? out : out - 1.0;", "}", "}"), f)
  for (backend in c("autodiff(reverse)", "autodiff(forward)"))
  {
    lines = readLines(f)
    lines[3] = paste("  factor lik = density(log = cpp::log_lik, gradient = ", backend, ")", sep = "")
    writeLines(lines, f)
    checked = ilike::check_gradient(ilike::compile(f), list(a = 1.3, b = c(0.8, 0.4)))
    expect_true(all(checked$error < 1e-6))
  }
})

test_that("autodiff(forward) and autodiff(reverse) need a log density written as a template", {
  f = tempfile(fileext = ".ilike")
  on.exit(unlink(f), add = TRUE)
  writeLines(autodiff_model("autodiff(forward)", "cpp::lik_gradient"), f)
  expect_error(ilike::compile(f), "autodiff(forward) needs the log density written in C++ as a template", fixed = TRUE)
  writeLines(autodiff_model("autodiff(reverse)", "cpp::lik_gradient"), f)
  expect_error(ilike::compile(f), "autodiff(reverse) needs the log density written in C++ as a template", fixed = TRUE)
})

test_that("by default, autodiff uses reverse mode for a variable of 10 elements or more", {
  # (C239) the generated gradient chooses by size; the two modes agree
  f = tempfile(fileext = ".ilike")
  on.exit(unlink(f), add = TRUE)
  model = function(gradient)
    c("ilike 1.0", "model {", paste("  factor lik = density(log = cpp::log_lik, gradient = ", gradient, ")", sep = ""), "}", "cpp {",
      "template <class T> T log_lik(const ParametersT<T> &parameters)",
      "{ const auto &b = parameters[\"b\"]; T out = 0; for (arma::uword j = 0; j < b.n_elem; ++j) out += log1p(exp(b[j] * (j + 1.0))) - b[j] * b[j]; return out; }",
      "}")
  b = seq(-1, 1, length.out = 12)
  gradients = list()
  for (gradient in c("autodiff", "autodiff(forward)", "autodiff(reverse)"))
  {
    writeLines(model(gradient), f)
    m = ilike::compile(f)
    gradients[[gradient]] = c(ilike:::evaluate_gradient_log(m, list(b = b), "b"), ilike:::evaluate_gradient_log(m, list(b = b[1:3]), "b"))
  }
  exact = function(b) { k = seq_along(b); k * plogis(b * k) - 2 * b }
  expect_equal(gradients[["autodiff"]], c(exact(b), exact(b[1:3])), tolerance = 1e-12)
  expect_equal(gradients[["autodiff(forward)"]], gradients[["autodiff(reverse)"]], tolerance = 1e-12)
})
